#!/usr/bin/env python3
"""Turn the official BIP 341 key-path vectors and the BIP 86 leaf vectors into
a C header for test_tx_vectors.c.  Every value is copied from the files; none
is computed here.

usage: gen-tx-vectors.py DIR > tx_vectors_data.h   (DIR from fetch-tx-vectors.sh)
"""
import json
import re
import sys


def s(v):
    return '"%s"' % v


def main():
    d = sys.argv[1]
    j = json.load(open(d + "/wallet-test-vectors.json"))
    out = ["/* Generated by wallet/tx/vectors/gen-tx-vectors.py from bitcoin/bips at",
           "   b34d9f751791d4feb22feff4f2ed00bcac83961b.  Do not edit. */", ""]
    kp = j["keyPathSpending"]
    assert len(kp) == 1
    v = kp[0]
    out.append("static const char BIP341_UNSIGNED[] = %s;" % s(v["given"]["rawUnsignedTx"]))
    out.append("static const char BIP341_SIGNED[] = %s;" % s(v["auxiliary"]["fullySignedTx"]))
    out.append("static const struct { const char *script; uint64_t amount; } BIP341_UTXOS[] = {")
    for u in v["given"]["utxosSpent"]:
        out.append("    {%s, UINT64_C(%d)}," % (s(u["scriptPubKey"]), u["amountSats"]))
    out.append("};")
    im = v["intermediary"]
    out.append("static const char *const BIP341_PARTS[5] = {%s, %s, %s, %s, %s};" % tuple(
        s(im[k]) for k in ("hashPrevouts", "hashAmounts", "hashScriptPubkeys",
                           "hashSequences", "hashOutputs")))
    out.append("static const struct {")
    out.append("    uint32_t index; const char *priv, *merkle_root; uint8_t hash_type;")
    out.append("    const char *internal_pub, *tweak, *tweaked_priv, *sigmsg, *sighash, *witness;")
    out.append("} BIP341_INPUTS[] = {")
    for i in v["inputSpending"]:
        g, m, e = i["given"], i["intermediary"], i["expected"]
        assert len(e["witness"]) == 1
        out.append("    {%d, %s, %s, %d, %s, %s, %s, %s, %s, %s}," % (
            g["txinIndex"], s(g["internalPrivkey"]), s(g["merkleRoot"] or ""), g["hashType"],
            s(m["internalPubkey"]), s(m["tweak"]), s(m["tweakedPrivkey"]), s(m["sigMsg"]),
            s(m["sigHash"]), s(e["witness"][0])))
    out.append("};")

    text = open(d + "/bip-0086.mediawiki").read()
    leaves = re.findall(r"// Account 0, [a-z ]+ address = (m/[0-9'/]+)\s*\n"
                        r"xprv\s*= (\w+)\s*\n.*?internal_key = (\w+)\s*\n"
                        r"output_key\s*= (\w+)\s*\nscriptPubKey = (\w+)", text, re.S)
    assert len(leaves) == 3, leaves
    out.append("static const struct { const char *path, *xprv, *internal_key, *output_key, *script; }"
               " BIP86_LEAVES[] = {")
    for leaf in leaves:
        out.append("    {%s}," % ", ".join(s(x) for x in leaf))
    out.append("};")
    print("\n".join(out))


if __name__ == "__main__":
    main()
